B64_bea9a46d
mkdir -p assets/mascot
echo 'Descargando oveja nueva...'
curl -fsSL -o /tmp/ovejita_vozalta_raw.png 'https://d8j0ntlcm91z4.cloudfront.net/user_357fcxDIqY9TMqfewNOAYaGunxR/hf_20260722_200855_b08188eb-8ef0-4940-8f97-e0a947066ecc.png'
python3 - <<'PY'
from PIL import Image
im = Image.open('/tmp/ovejita_vozalta_raw.png').convert('RGBA')
bbox = im.getbbox()
if bbox:
    im = im.crop(bbox)
w,h = im.size
side = int(max(w,h)/0.82)
canvas = Image.new('RGBA',(side,side),(0,0,0,0))
canvas.paste(im, ((side-w)//2,(side-h)//2), im)
canvas = canvas.resize((400,400), Image.LANCZOS)
canvas.save('assets/mascot/ovejita_vozalta.png')
print('ovejita_vozalta.png', canvas.size)
PY
echo "===V24_FILES_APPLIED==="
